def check_partition_efficient(S, k):
    lower = k - 6
    upper = 1
    if lower > upper:
        return False

    sums = {0}
    for x in S:
        new_sums = set()
        for s in sums:
            new_s = s + x
            if new_s <= upper:
                new_sums.add(new_s)
        sums.update(new_sums)

    for s in sums:
        if lower <= s <= upper:
            return True
    return False

def generate_random_set_fixed(k):
    import random
    n = random.randint(int(k), int(k*10))
    S = [random.uniform(0.1, 1.0) for _ in range(n)]
    s_sum = sum(S)
    # Scale S to have sum k
    # This might make some x > 1.
    S = [x * (k / s_sum) for x in S]
    if any(x > 1.0000000001 for x in S):
        return None
    return S

def search_counterexample(k, trials=50000):
    for _ in range(trials):
        S = generate_random_set_fixed(k)
        if S is not None:
            if not check_partition_efficient(S, k):
                return S
    return None

print(f"k=7: {search_counterexample(7)}")
print(f"k=6.8: {search_counterexample(6.8)}")
print(f"k=6.1: {search_counterexample(6.1)}")
